<script setup lang="ts">
import { post } from '../api/client';
import type { Run } from '../../../shared/contracts.js';
import { dateTime } from '../lib/format';
import { useFeedback, confirmAction } from '../composables/useFeedback';
import StatusTag from './StatusTag.vue';
import ErrorBanner from './ErrorBanner.vue';
defineProps<{ runs: Run[]; loading?: boolean }>();
const emit = defineEmits<{ refresh: [] }>();
const { busy, error, act } = useFeedback();
async function action(run: Run, type: 'stop' | 'resume' | 'retry' | 'notify') {
  if (type === 'stop' && !await confirmAction('停止后会保留已采集数据，可稍后继续此执行。')) return;
  await act(async () => { await post(`/runs/${run.id}/${type}`); emit('refresh'); }, type === 'retry' ? '已创建关联重试执行，原报告保持不变' : type === 'notify' ? '汇总通知已受理' : '操作成功');
}
</script>
<template><ErrorBanner :message="error" /><el-table :data="runs" v-loading="loading" row-key="id" empty-text="暂无执行记录，请先创建并运行任务。" stripe><el-table-column type="expand"><template #default="{ row }"><div class="run-details"><p><b>执行 ID</b> {{ row.id }} <span v-if="row.parentRunId"> / 重试自 {{ row.parentRunId }}</span></p><p>{{ row.message || '暂无执行说明' }}</p><div class="inline-metrics"><span>入库 SKU {{ row.rows }}</span><span>已检查 {{ row.checked }}</span><span>白名单排除 {{ row.excluded }}</span><span>命中 {{ row.matched }}</span><span>无法判断 {{ row.unknown }}</span></div><p>启动：{{ dateTime(row.startedAt) }} · 结束：{{ dateTime(row.finishedAt) }}</p><p v-if="row.failedProductIds.length">失败商品：{{ row.failedProductIds.join('、') }}</p><router-link :to="{ path: '/prices', state: { priceQuery: { view: 'sku', runId: row.id } } }">查询本批次价格</router-link><router-link :to="{ path: '/alerts', query: { runId: row.id } }">查看本次预警</router-link></div></template></el-table-column><el-table-column label="任务 / 店铺" min-width="210"><template #default="{ row }"><strong>{{ row.taskName || '临时采集' }}</strong><div class="cell-sub">{{ row.shopName }}</div></template></el-table-column><el-table-column label="状态" width="145"><template #default="{ row }"><StatusTag :value="row.status" /></template></el-table-column><el-table-column label="商品进度" min-width="170"><template #default="{ row }"><div class="progress-label">{{ row.processed }} / {{ row.expected || '待发现' }}<span>失败 {{ row.failed }}</span></div><el-progress :percentage="row.expected ? Math.min(100, Math.round(row.processed / row.expected * 100)) : 0" :show-text="false" :stroke-width="5" /></template></el-table-column><el-table-column prop="matched" label="命中 SKU" width="95" /><el-table-column label="通知" width="105"><template #default="{ row }"><StatusTag :value="row.notificationStatus" /></template></el-table-column><el-table-column label="创建时间" min-width="170"><template #default="{ row }">{{ dateTime(row.createdAt) }}</template></el-table-column><el-table-column label="操作" min-width="220" fixed="right"><template #default="{ row }"><el-button v-if="['queued', 'running', 'auth_required'].includes(row.status)" text type="danger" :disabled="busy" @click="action(row, 'stop')">停止</el-button><el-button v-if="['stopped', 'recoverable', 'auth_required'].includes(row.status)" text type="primary" :disabled="busy" @click="action(row, 'resume')">继续 / 恢复</el-button><el-button v-if="['success', 'partial', 'failed'].includes(row.status) && row.failedProductIds.length" text type="primary" :disabled="busy" @click="action(row, 'retry')">重试失败项</el-button><el-button v-if="['success', 'partial', 'failed'].includes(row.status)" text :disabled="busy" @click="action(row, 'notify')">重发汇总</el-button></template></el-table-column></el-table></template>
